using System;
using System.Collections;
using System.Collections.Generic;

namespace TypeSystemDemo
{
    // --- 值类型：readonly struct，推荐写法 ---
    public readonly struct Point
    {
        public double X { get; }
        public double Y { get; }
        public Point(double x, double y) { X = x; Y = y; }
        public override string ToString() => $"({X}, {Y})";
    }

    // --- 引用类型 ---
    public class Person
    {
        public string Name { get; set; }
        public int Age { get; set; }
        public Person(string name, int age) { Name = name; Age = age; }
    }

    class Program
    {
        static void Main()
        {
            // 1) 值类型赋值是拷贝
            Point p1 = new Point(1, 2);
            Point p2 = p1;   // 拷贝值
            var p3 = p1 with { X = 100 }; // C# 10 record struct with 表达式
            Console.WriteLine($"p1={p1}, p2={p2}, p3={p3}");
            // p1=(1, 2) 不受影响，p3=(100, 2) 是新值

            // 2) 引用类型赋值是共享引用
            Person alice = new Person("Alice", 25);
            Person alsoAlice = alice; // 同一个对象
            alsoAlice.Name = "Bob";
            Console.WriteLine(alice.Name); // Bob —— 修改了同一对象

            // 3) 装箱与拆箱
            int num = 42;
            object boxed = num;          // 装箱：堆分配 + 拷贝
            int unboxed = (int)boxed;    // 拆箱：类型检查 + 拷贝回栈
            Console.WriteLine(num == unboxed); // true

            // 4) 循环装箱 vs 泛型
            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
            ArrayList arrayList = new ArrayList();
            for (int i = 0; i < 1_000_000; i++) arrayList.Add(i); // 每次装箱
            stopwatch.Stop();
            Console.WriteLine($"ArrayList with boxing: {stopwatch.ElapsedMilliseconds}ms");

            stopwatch.Restart();
            List<int> list = new List<int>();
            for (int i = 0; i < 1_000_000; i++) list.Add(i); // 无装箱
            stopwatch.Stop();
            Console.WriteLine($"List<int> without boxing: {stopwatch.ElapsedMilliseconds}ms");

            // 5) 可空值类型 Nullable<T>
            int? nullableAge = null;
            Console.WriteLine(nullableAge.HasValue);       // false
            nullableAge = 30;
            Console.WriteLine(nullableAge.Value);          // 30
            int result = nullableAge ?? 0;                 // 空合并
            int ageOrDefault = nullableAge.GetValueOrDefault(-1);

            // 6) 可空引用类型（编译器静态分析，非运行时改变）
            #nullable enable
            string? maybeNull = null;   // 标记：此变量可能为 null
            string definitely = "hello"; // 标记：此变量不应为 null
            // definitely = null;         // 编译器警告 CS8600
            Console.WriteLine(maybeNull?.Length);  // null 条件运算符
            #nullable restore
        }
    }
}
